const response = $input.first().json;

// Handle format array produk Olsera (response.data, response.products, atau response langsung array)
const items = Array.isArray(response) 
  ? response 
  : (response.data || response.products || response.items || []);

if (!items || items.length === 0) {
  return [];
}

return items.map((product) => {
  // Normalisasi & pemetaan field dari Olsera POS ke skema PostgreSQL Grandivo Store
  const olseraId = String(product.id || product.product_id || '').trim();
  const name = String(product.name || product.title || '').trim();
  const sku = String(product.sku || product.barcode || olseraId).trim();
  const price = parseFloat(product.sell_price || product.price || product.variant_price || 0);
  const buyPrice = parseFloat(product.buy_price || product.cost_price || 0);
  const stock = parseInt(product.stock || product.total_stock || product.qty || 0, 10);
  const weight = parseFloat(product.weight || product.weight_gram || 0);
  const description = String(product.description || product.note || '').trim();
  const category = String(product.category_name || product.category || 'Umum').trim();
  const brand = String(product.brand_name || product.brand || 'Grandivo').trim();
  const imageUrl = String(product.photo || product.image_url || product.picture || '').trim();
  const isActive = product.is_active !== undefined ? Boolean(product.is_active) : true;

  return {
    json: {
      olsera_id: olseraId,
      name: name,
      sku: sku,
      price: price,
      buy_price: buyPrice,
      stock: stock,
      weight: weight,
      description: description,
      category: category,
      brand: brand,
      image_url: imageUrl,
      is_active: isActive,
      synced_at: new Date().toISOString()
    }
  };
});

const totalSynced = $input.all().length;
const timestamp = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });

return [{
  json: {
    status: 'SUCCESS',
    message: `Berhasil sinkronisasi ${totalSynced} produk dari Olsera ke PostgreSQL.`,
    total_synced: totalSynced,
    synced_at_wib: timestamp
  }
}];
